"""Display helpers."""

from __future__ import annotations

import os
from dataclasses import dataclass


SUPPRESS_BANNER = bool(os.environ.get("YDATA_SUPPRESS_BANNER"))
_displayed_banner = False


def in_jupyter_notebook() -> bool:
    try:
        from IPython import get_ipython  # type: ignore
    except Exception:
        return False
    shell = get_ipython()
    return shell is not None and shell.__class__.__name__ != "TerminalInteractiveShell"


@dataclass
class DisplayInfo:
    title: str
    info_text: str
    link: str = "https://ydata.ai/register"

    def display_message(self) -> None:
        message = f"{self.title}: {self.info_text} ({self.link})"
        if in_jupyter_notebook():
            try:
                from IPython.display import HTML, display  # type: ignore

                display(HTML(f"<strong>{self.title}</strong>: {self.info_text} <a href='{self.link}'>{self.link}</a>"))
                return
            except Exception:
                pass
        print(message)


def display_banner() -> None:
    global _displayed_banner
    if SUPPRESS_BANNER or _displayed_banner:
        return
    _displayed_banner = True
    DisplayInfo(
        title="ydata-profiling",
        info_text="Automated exploratory data analysis",
        link="https://github.com/ydataai/ydata-profiling",
    ).display_message()

