"""DataFrame helpers."""

from __future__ import annotations

import hashlib
import re
import unicodedata
import warnings
from pathlib import Path
from typing import Any, Dict, Optional

import pandas as pd

from ydata_profiling.config import Settings

HASH_PREFIX = "2@"


def rename_index(df: pd.DataFrame) -> pd.DataFrame:
    if "index" in df.columns:
        df = df.rename(columns={"index": "df_index"})
    if any(name == "index" for name in df.index.names):
        df.index.names = ["df_index" if name == "index" else name for name in df.index.names]
    return df


def hash_dataframe(df: pd.DataFrame) -> str:
    hashed = pd.util.hash_pandas_object(df, index=True)
    digest = hashlib.sha256("\n".join(map(str, hashed.tolist())).encode("utf-8")).hexdigest()
    return f"{HASH_PREFIX}{digest}"


def slugify(value: str, allow_unicode: bool = False) -> str:
    value = str(value)
    if allow_unicode:
        value = unicodedata.normalize("NFKC", value)
    else:
        value = unicodedata.normalize("NFKD", value).encode("ascii", "ignore").decode("ascii")
    value = re.sub(r"[^\w\s-]", "", value.lower())
    return re.sub(r"[-\s]+", "-", value).strip("-_")


def is_supported_compression(file_extension: str) -> bool:
    return file_extension in {".bz2", ".gz", ".xz", ".zip"}


def uncompressed_extension(file_name: Path) -> str:
    suffixes = file_name.suffixes
    if suffixes and is_supported_compression(suffixes[-1]) and len(suffixes) > 1:
        return suffixes[-2]
    return file_name.suffix


def warn_read(extension: str) -> None:
    warnings.warn(f"Falling back to pandas default reader for {extension}", stacklevel=2)


def read_pandas(file_name: Path) -> pd.DataFrame:
    extension = uncompressed_extension(file_name)
    if extension in {".csv", ".txt"}:
        return pd.read_csv(file_name)
    if extension in {".json"}:
        return pd.read_json(file_name)
    if extension in {".xls", ".xlsx"}:
        return pd.read_excel(file_name)
    if extension in {".parquet"}:
        return pd.read_parquet(file_name)
    warn_read(extension)
    return pd.read_csv(file_name)


def sort_column_names(dct: dict, sort: Optional[str] = None) -> dict:
    if sort in {"ascending", "asc"}:
        return {k: dct[k] for k in sorted(dct)}
    if sort in {"descending", "desc"}:
        return {k: dct[k] for k in sorted(dct, reverse=True)}
    return dict(dct)


def expand_mixed(df: pd.DataFrame, types: Any = None) -> pd.DataFrame:
    return df


def redact_key(data: dict, config: Settings) -> dict:
    return {f"REDACTED_{i}": value for i, value in enumerate(data.values(), start=1)}


def redact_value(data: dict, config: Settings) -> dict:
    return {key: f"REDACTED_{i}" for i, key in enumerate(data.keys(), start=1)}


def preprocess(config: Settings, df: Any) -> Any:
    if isinstance(df, pd.DataFrame):
        df = rename_index(df.copy())
        df.columns = [str(col) for col in df.columns]
    return df


def get_custom_sample(sample: dict):
    from ydata_profiling.model.sample import Sample

    return [
        Sample(
            name=sample.get("name", "Custom"),
            caption=sample.get("caption"),
            data=sample["data"],
        )
    ]

