"""Simple type relation helpers."""

from __future__ import annotations

import functools
from typing import Callable, Dict

import pandas as pd

from ydata_profiling.utils.versions import is_pandas_1


def is_nullable(series: pd.Series, state: dict) -> bool:
    return series.count() > 0


def try_func(fn: Callable) -> Callable:
    @functools.wraps(fn)
    def inner(series: pd.Series, *args, **kwargs) -> bool:
        try:
            return bool(fn(series, *args, **kwargs))
        except Exception:
            return False

    return inner


def series_handle_nulls(
    fn: Callable[[pd.Series, dict], bool]
) -> Callable[[pd.Series, dict], bool]:
    @functools.wraps(fn)
    def inner(series: pd.Series, state: dict, *args, **kwargs):
        if getattr(series, "hasnans", False):
            series = series.dropna()
        return fn(series, state, *args, **kwargs)

    return inner


@series_handle_nulls
def series_is_string(series: pd.Series, state: dict) -> bool:
    return not series.empty and series.map(lambda value: isinstance(value, str)).all()


def string_to_bool(series: pd.Series, state: dict, k: Dict[str, bool]) -> pd.Series:
    return series.astype(str).str.lower().map(k)


def string_is_bool(series: pd.Series, state: dict, k: Dict[str, bool]) -> bool:
    @series_handle_nulls
    @try_func
    def tester(s: pd.Series, inner_state: dict) -> bool:
        lowered = s.astype(str).str.lower()
        return lowered.isin(k.keys()).all()

    return tester(series, state)


def numeric_is_category(series: pd.Series, state: dict, k) -> bool:
    threshold = k.vars.num.low_categorical_threshold
    if threshold <= 0:
        return False
    n_unique = series.nunique(dropna=True)
    return 1 <= n_unique <= threshold


def to_category(series: pd.Series, state: dict) -> pd.Series:
    return series.astype(str)


@series_handle_nulls
def string_is_category(series: pd.Series, state: dict, k) -> bool:
    n = max(len(series), 1)
    n_unique = series.nunique(dropna=True)
    if string_is_bool(series, state, k.vars.bool.mappings):
        return False
    return (
        1 <= n_unique <= k.vars.cat.cardinality_threshold
        and (n_unique / n) <= k.vars.cat.percentage_cat_threshold
    )


@series_handle_nulls
def string_is_datetime(series: pd.Series, state: dict) -> bool:
    converted = string_to_datetime(series, state)
    return converted.notna().any()


@series_handle_nulls
def string_is_numeric(series: pd.Series, state: dict, k) -> bool:
    if string_is_bool(series, state, k.vars.bool.mappings):
        return False
    converted = string_to_numeric(series, state)
    if converted.notna().sum() == 0:
        return False
    return not numeric_is_category(converted.dropna(), state, k)


def string_to_datetime(series: pd.Series, state: dict) -> pd.Series:
    if is_pandas_1():
        return pd.to_datetime(series, errors="coerce")
    return pd.to_datetime(series, format="mixed", errors="coerce")


def string_to_numeric(series: pd.Series, state: dict) -> pd.Series:
    return pd.to_numeric(series, errors="coerce")


def to_bool(series: pd.Series) -> pd.Series:
    dtype = "boolean" if series.isna().any() else bool
    return series.astype(dtype)


@series_handle_nulls
def object_is_bool(series: pd.Series, state: dict) -> bool:
    return series.map(lambda value: isinstance(value, bool)).all()

