"""Summarizer implementations."""

from __future__ import annotations

from dataclasses import asdict, is_dataclass
from typing import Any, Dict, List, Type, Union

import numpy as np
import pandas as pd

from ydata_profiling.model.handler import Handler, _dtype_name


def format_summary(summary: Union[dict, Any]) -> dict:
    def fmt(value: Any) -> Any:
        if is_dataclass(value):
            return {k: fmt(v) for k, v in asdict(value).items()}
        if isinstance(value, pd.DataFrame):
            return [fmt(record) for record in value.to_dict(orient="records")]
        if isinstance(value, pd.Series):
            return {str(k): fmt(v) for k, v in value.to_dict().items()}
        if isinstance(value, np.ndarray):
            return value.tolist()
        if isinstance(value, dict):
            return {str(k): fmt(v) for k, v in value.items()}
        if isinstance(value, (list, tuple, set)):
            return [fmt(item) for item in value]
        if hasattr(value, "isoformat"):
            try:
                return value.isoformat()
            except Exception:
                pass
        if hasattr(value, "value") and not isinstance(value, (str, bytes)):
            try:
                return value.value
            except Exception:
                pass
        if isinstance(value, (np.integer, np.floating)):
            return value.item()
        return value

    if is_dataclass(summary):
        return fmt(summary)
    return fmt(dict(summary))


def _redact_column(column: Dict[str, Any]) -> Dict[str, Any]:
    redacted = dict(column)
    for key in (
        "first_rows",
        "value_counts_without_nan",
        "value_counts_index_sorted",
        "word_counts",
        "character_counts",
    ):
        if key in redacted:
            redacted[key] = "REDACTED"
    return redacted


def redact_summary(summary: dict, config) -> dict:
    result = dict(summary)
    variables = {}
    for name, description in result.get("variables", {}).items():
        dtype = description.get("type")
        if dtype == "Categorical" and config.vars.cat.redact:
            variables[name] = _redact_column(description)
        elif dtype == "Text" and config.vars.text.redact:
            variables[name] = _redact_column(description)
        else:
            variables[name] = description
    result["variables"] = variables
    return result


class BaseSummarizer(Handler):
    """A base summarizer."""

    def summarize(self, config, series: pd.Series, dtype: Type[Any]) -> dict:
        dtype_name = _dtype_name(dtype)
        summary = {"type": dtype_name, "name": series.name}
        summary = self.handle(dtype_name, config, series, summary)
        summary["type"] = dtype_name
        summary["name"] = series.name
        return summary


class ProfilingSummarizer(BaseSummarizer):
    """A summarizer for DataFrames."""

    def __init__(self, typeset, use_spark: bool = False):
        self._use_spark = use_spark
        self._summary_map = self._create_summary_map()
        super().__init__(self._summary_map, typeset)

    @property
    def summary_map(self) -> Dict[str, List[Any]]:
        return self._summary_map

    def _create_summary_map(self) -> Dict[str, List[Any]]:
        if self._use_spark:
            from ydata_profiling.model.spark_backend import (
                describe_boolean_1d_spark,
                describe_categorical_1d_spark,
                describe_counts_spark,
                describe_date_1d_spark,
                describe_file_1d_spark,
                describe_generic_spark,
                describe_image_1d_spark,
                describe_numeric_1d_spark,
                describe_path_1d_spark,
                describe_supported_spark,
                describe_text_1d_spark,
                describe_timeseries_1d_spark,
                describe_url_1d_spark,
            )

            generic = [describe_counts_spark, describe_generic_spark]
            supported = generic + [describe_supported_spark]
            return {
                "Unsupported": generic,
                "Numeric": supported + [describe_numeric_1d_spark],
                "DateTime": supported + [describe_date_1d_spark],
                "Text": supported + [describe_text_1d_spark],
                "Categorical": supported + [describe_categorical_1d_spark],
                "Boolean": supported + [describe_boolean_1d_spark],
                "URL": supported + [describe_url_1d_spark],
                "Path": supported + [describe_path_1d_spark],
                "File": supported + [describe_file_1d_spark],
                "Image": supported + [describe_image_1d_spark],
                "TimeSeries": supported + [describe_timeseries_1d_spark],
            }

        from ydata_profiling.model.pandas_backend import (
            pandas_describe_boolean_1d,
            pandas_describe_categorical_1d,
            pandas_describe_counts,
            pandas_describe_date_1d,
            pandas_describe_file_1d,
            pandas_describe_generic,
            pandas_describe_image_1d,
            pandas_describe_numeric_1d,
            pandas_describe_path_1d,
            pandas_describe_supported,
            pandas_describe_text_1d,
            pandas_describe_timeseries_1d,
            pandas_describe_url_1d,
        )

        generic = [pandas_describe_counts, pandas_describe_generic]
        supported = generic + [pandas_describe_supported]
        return {
            "Unsupported": generic,
            "Numeric": supported + [pandas_describe_numeric_1d],
            "DateTime": supported + [pandas_describe_date_1d],
            "Text": supported + [pandas_describe_text_1d],
            "Categorical": supported + [pandas_describe_categorical_1d],
            "Boolean": supported + [pandas_describe_boolean_1d],
            "URL": supported + [pandas_describe_url_1d],
            "Path": supported + [pandas_describe_path_1d],
            "File": supported + [pandas_describe_file_1d],
            "Image": supported + [pandas_describe_image_1d],
            "TimeSeries": supported + [pandas_describe_timeseries_1d],
        }

