"""Logic for alerting the user on possibly problematic patterns in the data."""

from __future__ import annotations

from dataclasses import dataclass
from enum import Enum, auto, unique
from typing import Dict, List, Optional, Set

import pandas as pd

from ydata_profiling.config import Settings
from ydata_profiling.model.correlations import perform_check_correlation
from ydata_profiling.utils.dataframe import slugify


@unique
class AlertType(Enum):
    CONSTANT = auto()
    ZEROS = auto()
    HIGH_CORRELATION = auto()
    HIGH_CARDINALITY = auto()
    UNSUPPORTED = auto()
    DUPLICATES = auto()
    NEAR_DUPLICATES = auto()
    SKEWED = auto()
    IMBALANCE = auto()
    MISSING = auto()
    INFINITE = auto()
    TYPE_DATE = auto()
    UNIQUE = auto()
    DIRTY_CATEGORY = auto()
    CONSTANT_LENGTH = auto()
    REJECTED = auto()
    UNIFORM = auto()
    NON_STATIONARY = auto()
    SEASONAL = auto()
    EMPTY = auto()


class Alert:
    _anchor_id: Optional[str] = None

    def __init__(
        self,
        alert_type: AlertType,
        values: Optional[Dict] = None,
        column_name: Optional[str] = None,
        fields: Optional[Set] = None,
        is_empty: bool = False,
    ):
        self.alert_type = alert_type
        self.values = values or {}
        self.column_name = column_name
        self.fields = fields or set()
        self.is_empty = is_empty

    @property
    def alert_type_name(self) -> str:
        return self.alert_type.name.lower()

    @property
    def anchor_id(self) -> Optional[str]:
        if self._anchor_id is not None:
            return self._anchor_id
        if self.column_name is None:
            return None
        self._anchor_id = slugify(f"{self.column_name}-{self.alert_type_name}")
        return self._anchor_id

    def fmt(self) -> str:
        description = self._get_description()
        if self.column_name:
            return f"{self.column_name}: {description}"
        return description

    def _get_description(self) -> str:
        return self.alert_type_name.replace("_", " ")

    def __repr__(self):
        return self.fmt()


def _make_alert(name: str, alert_type: AlertType):
    return type(
        name,
        (Alert,),
        {
            "__init__": lambda self, values=None, column_name=None, is_empty=False, _t=alert_type: Alert.__init__(
                self, _t, values=values, column_name=column_name, is_empty=is_empty
            ),
        },
    )


ConstantLengthAlert = _make_alert("ConstantLengthAlert", AlertType.CONSTANT_LENGTH)
ConstantAlert = _make_alert("ConstantAlert", AlertType.CONSTANT)
DuplicatesAlert = _make_alert("DuplicatesAlert", AlertType.DUPLICATES)
NearDuplicatesAlert = _make_alert("NearDuplicatesAlert", AlertType.NEAR_DUPLICATES)
EmptyAlert = _make_alert("EmptyAlert", AlertType.EMPTY)
HighCardinalityAlert = _make_alert("HighCardinalityAlert", AlertType.HIGH_CARDINALITY)
DirtyCategoryAlert = _make_alert("DirtyCategoryAlert", AlertType.DIRTY_CATEGORY)
HighCorrelationAlert = _make_alert("HighCorrelationAlert", AlertType.HIGH_CORRELATION)
ImbalanceAlert = _make_alert("ImbalanceAlert", AlertType.IMBALANCE)
InfiniteAlert = _make_alert("InfiniteAlert", AlertType.INFINITE)
MissingAlert = _make_alert("MissingAlert", AlertType.MISSING)
NonStationaryAlert = _make_alert("NonStationaryAlert", AlertType.NON_STATIONARY)
SeasonalAlert = _make_alert("SeasonalAlert", AlertType.SEASONAL)
SkewedAlert = _make_alert("SkewedAlert", AlertType.SKEWED)
TypeDateAlert = _make_alert("TypeDateAlert", AlertType.TYPE_DATE)
UniformAlert = _make_alert("UniformAlert", AlertType.UNIFORM)
UniqueAlert = _make_alert("UniqueAlert", AlertType.UNIQUE)
UnsupportedAlert = _make_alert("UnsupportedAlert", AlertType.UNSUPPORTED)
ZerosAlert = _make_alert("ZerosAlert", AlertType.ZEROS)
RejectedAlert = _make_alert("RejectedAlert", AlertType.REJECTED)


def alert_value(value: float) -> bool:
    return bool(value and value > 0)


def skewness_alert(v: float, threshold: int) -> bool:
    return abs(v) > threshold


def type_date_alert(series: pd.Series) -> bool:
    converted = pd.to_datetime(series.astype(str), errors="coerce")
    return converted.notna().sum() == len(series) and len(series) > 0


def generic_alerts(summary: dict) -> List[Alert]:
    alerts: List[Alert] = []
    if alert_value(summary.get("p_missing", 0.0)):
        alerts.append(MissingAlert())
    if summary.get("n_distinct") == 1 and summary.get("count", 0) > 0:
        alerts.append(ConstantAlert())
    if summary.get("is_unique"):
        alerts.append(UniqueAlert())
    return alerts


def supported_alerts(summary: dict) -> List[Alert]:
    alerts: List[Alert] = []
    if summary.get("type") == "Unsupported":
        alerts.append(UnsupportedAlert())
    return alerts


def unsupported_alerts() -> List[Alert]:
    return [UnsupportedAlert()]


def numeric_alerts(config: Settings, summary: dict) -> List[Alert]:
    alerts: List[Alert] = []
    if summary.get("n_zeros", 0) > 0:
        alerts.append(ZerosAlert())
    if summary.get("n_infinite", 0) > 0:
        alerts.append(InfiniteAlert())
    if skewness_alert(summary.get("skewness", 0.0), config.vars.num.skewness_threshold):
        alerts.append(SkewedAlert())
    if summary.get("std", 0.0) == 0 and summary.get("count", 0) > 1:
        alerts.append(UniformAlert())
    return alerts


def timeseries_alerts(config: Settings, summary: dict) -> List[Alert]:
    alerts: List[Alert] = []
    if not summary.get("is_stationary", True):
        alerts.append(NonStationaryAlert())
    if summary.get("seasonality_presence"):
        alerts.append(SeasonalAlert())
    return alerts


def categorical_alerts(config: Settings, summary: dict) -> List[Alert]:
    alerts: List[Alert] = []
    if summary.get("n_distinct", 0) > config.vars.cat.cardinality_threshold:
        alerts.append(HighCardinalityAlert())
    if summary.get("imbalance", 0.0) > config.vars.cat.imbalance_threshold:
        alerts.append(ImbalanceAlert())
    if summary.get("max_length") == summary.get("min_length") and summary.get("count", 0) > 0:
        alerts.append(ConstantLengthAlert())
    if summary.get("dirty_categories"):
        alerts.append(DirtyCategoryAlert())
    return alerts


def boolean_alerts(config: Settings, summary: dict) -> List[Alert]:
    alerts: List[Alert] = []
    if summary.get("imbalance", 0.0) > config.vars.bool.imbalance_threshold:
        alerts.append(ImbalanceAlert())
    return alerts


def check_table_alerts(table: dict) -> List[Alert]:
    alerts: List[Alert] = []
    if table.get("n", 0) == 0:
        alerts.append(EmptyAlert())
    if table.get("n_duplicates", 0) > 0:
        alerts.append(DuplicatesAlert())
    return alerts


def check_variable_alerts(config: Settings, col: str, description: dict) -> List[Alert]:
    dtype = description.get("type")
    alerts = generic_alerts(description)
    if dtype == "Unsupported":
        alerts.extend(unsupported_alerts())
    else:
        alerts.extend(supported_alerts(description))
        if dtype in {"Categorical", "Text"}:
            alerts.extend(categorical_alerts(config, description))
        if dtype in {"Numeric", "TimeSeries"}:
            alerts.extend(numeric_alerts(config, description))
        if dtype == "TimeSeries":
            alerts.extend(timeseries_alerts(config, description))
        if dtype == "Boolean":
            alerts.extend(boolean_alerts(config, description))
    for alert in alerts:
        alert.column_name = col
        alert.values = description
    return alerts


def check_correlation_alerts(config: Settings, correlations: dict) -> List[Alert]:
    alerts: List[Alert] = []
    for name, matrix in correlations.items():
        if matrix is None:
            continue
        corr_cfg = config.correlations.get(name)
        threshold = corr_cfg.threshold if hasattr(corr_cfg, "threshold") else corr_cfg.get("threshold", 0.5)
        selected = perform_check_correlation(matrix, threshold)
        for column, others in selected.items():
            alert = HighCorrelationAlert(column_name=column)
            alert.values = {"correlation_name": name, "with": others}
            alerts.append(alert)
    return alerts


def get_alerts(
    config: Settings,
    table_stats: dict,
    series_description: dict,
    correlations: dict,
) -> List[Alert]:
    alerts = check_table_alerts(table_stats)
    for column, description in series_description.items():
        alerts.extend(check_variable_alerts(config, column, description))
    alerts.extend(check_correlation_alerts(config, correlations))
    return sorted(alerts, key=lambda alert: (alert.alert_type.value, alert.column_name or ""))

