"""Missing-data helpers."""

from __future__ import annotations

from typing import Any, Callable, Dict, Optional, Sized

import pandas as pd

from ydata_profiling.config import Settings


class MissingDataBackend:
    def __init__(self, df: Sized):
        if df.__class__.__module__.startswith("pyspark"):
            from ydata_profiling.model import spark_backend as backend
        else:
            from ydata_profiling.model import pandas_backend as backend
        self.backend = backend

    def get_method(self, method_name: str) -> Callable:
        return getattr(self.backend, method_name)


class MissingData:
    _method_name: str = ""

    def compute(
        self, config: Settings, df: Sized, backend: MissingDataBackend
    ) -> Optional[Sized]:
        return backend.get_method(self._method_name)(config, df)


class MissingBar(MissingData):
    _method_name = "missing_bar"


class MissingMatrix(MissingData):
    _method_name = "missing_matrix"


class MissingHeatmap(MissingData):
    _method_name = "missing_heatmap"


def get_missing_active(config: Settings, table_stats: dict) -> Dict[str, Any]:
    active = {}
    if table_stats.get("n_cells_missing", 0) <= 0:
        return active
    if config.missing_diagrams.get("bar"):
        active["bar"] = {"name": "Count", "caption": "Missing values bar chart", "matrix": MissingBar()}
    if config.missing_diagrams.get("matrix"):
        active["matrix"] = {"name": "Matrix", "caption": "Missing values matrix", "matrix": MissingMatrix()}
    if config.missing_diagrams.get("heatmap"):
        active["heatmap"] = {"name": "Heatmap", "caption": "Missing values correlation", "matrix": MissingHeatmap()}
    return active


def get_missing_diagram(
    config: Settings, df: pd.DataFrame, settings: Dict[str, Any]
) -> Optional[Dict[str, Any]]:
    backend = MissingDataBackend(df)
    image = settings["matrix"].compute(config, df, backend)
    if image is None:
        return None
    return {
        "name": settings["name"],
        "image": image,
        "caption": settings["caption"],
    }

