"""Expectation helpers."""

from __future__ import annotations

from typing import Any, Tuple


def _append(batch: Any, expectation: dict) -> Any:
    if batch is None:
        return {"expectations": [expectation]}
    batch.setdefault("expectations", []).append(expectation)
    return batch


def generic_expectations(name: str, summary: dict, batch: Any, *args) -> Tuple[str, dict, Any]:
    batch = _append(batch, {"column": name, "type": "not_null", "mostly": 1 - summary.get("p_missing", 0.0)})
    if summary.get("is_unique"):
        batch = _append(batch, {"column": name, "type": "unique"})
    return name, summary, batch


def numeric_expectations(name: str, summary: dict, batch: Any, *args) -> Tuple[str, dict, Any]:
    batch = _append(batch, {"column": name, "type": "numeric"})
    if "min" in summary and "max" in summary:
        batch = _append(batch, {"column": name, "type": "between", "min": summary["min"], "max": summary["max"]})
    return name, summary, batch


def categorical_expectations(name: str, summary: dict, batch: Any, *args) -> Tuple[str, dict, Any]:
    if summary.get("n_distinct", 0) <= 10 or summary.get("p_distinct", 1.0) <= 0.2:
        values = list(getattr(summary.get("value_counts_without_nan"), "index", []))
        batch = _append(batch, {"column": name, "type": "in_set", "values": values})
    return name, summary, batch


def datetime_expectations(name: str, summary: dict, batch: Any, *args) -> Tuple[str, dict, Any]:
    if "min" in summary and "max" in summary:
        batch = _append(batch, {"column": name, "type": "datetime_between", "min": summary["min"], "max": summary["max"]})
    return name, summary, batch


def path_expectations(name: str, summary: dict, batch: Any, *args) -> Tuple[str, dict, Any]:
    return name, summary, batch


def image_expectations(name: str, summary: dict, batch: Any, *args) -> Tuple[str, dict, Any]:
    return name, summary, batch


def url_expectations(name: str, summary: dict, batch: Any, *args) -> Tuple[str, dict, Any]:
    return name, summary, batch


def file_expectations(name: str, summary: dict, batch: Any, *args) -> Tuple[str, dict, Any]:
    return name, summary, batch

