) -> Tuple[Settings, pd.Series, dict]:
    dt = to_datetime(series)
    summary.update(
        {
            "min": dt.min(),
            "max": dt.max(),
            "range": dt.max() - dt.min() if len(dt) else pd.Timedelta(0),
        }
    )
    timestamps = dt.dropna().map(pd.Timestamp.timestamp).to_numpy()
    summary.update(histogram_compute(config, timestamps, summary.get("n_distinct", 0)))
    return config, dt, summary


@series_hashable
@series_handle_nulls
def pandas_describe_text_1d(
    config: Settings,
    series: pd.Series,
    summary: dict,
) -> Tuple[Settings, pd.Series, dict]:
