        summary.update(named_aggregate_summary(lengths, "length"))
        summary.update(histogram_compute(config, lengths.to_numpy(), int(lengths.nunique()), name="histogram_length"))
    if config.vars.text.words:
        words = string_series.str.split().map(len)
        summary.update(named_aggregate_summary(words, "words"))
    if config.vars.text.characters:
        summary.update(unicode_summary_vc(vc))
