    return summarizer.summarize(config, series, dtype)


def pandas_get_series_descriptions(config, df, summarizer, typeset, pbar) -> dict:
    descriptions = {}
    for name, series in df.items():
        pbar.set_postfix_str(f"Describe variable: {name}")
        descriptions[name] = pandas_describe_1d(config, series, summarizer, typeset)
        pbar.update()
    return sort_column_names(descriptions, config.sort)


@get_duplicates.register
def pandas_get_duplicates(
    config: Settings, df: pd.DataFrame, supported_columns: Sequence
) -> Tuple[Dict[str, Any], Optional[pd.DataFrame]]:
    if not supported_columns:
        return {"n_duplicates": 0, "p_duplicates": 0.0}, None
    duplicated = df.duplicated(subset=list(supported_columns), keep=False)
    duplicate_rows = df.loc[duplicated, list(supported_columns)].copy()
    if duplicate_rows.empty:
        return {"n_duplicates": 0, "p_duplicates": 0.0}, duplicate_rows
    counts = duplicate_rows.value_counts().rename(config.duplicates.key).reset_index()
    counts = counts.sort_values(config.duplicates.key, ascending=False).head(config.duplicates.head)
    n_duplicates = int(duplicated.sum())
    return {
        "n_duplicates": n_duplicates,
        "p_duplicates": float(n_duplicates / max(len(df), 1)),
    }, counts


@get_sample.register
def pandas_get_sample(config: Settings, df: pd.DataFrame) -> List[Sample]:
    samples: List[Sample] = []
    if config.samples.head:
        samples.append(Sample(name="Head", data=df.head(config.samples.head), caption="First rows"))
    if config.samples.tail:
        samples.append(Sample(name="Tail", data=df.tail(config.samples.tail), caption="Last rows"))
    if config.samples.random:
        samples.append(
            Sample(
                name="Random",
                data=df.sample(min(config.samples.random, len(df)), random_state=42),
                caption="Random sample",
            )
        )
    return samples


@get_table_stats.register
def pandas_get_table_stats(
    config: Settings, df: pd.DataFrame, variable_stats: dict
) -> dict:
    n = len(df)
    n_var = len(df.columns)
    n_missing = int(df.isna().sum().sum())
    types = Counter(description.get("type", "Unsupported") for description in variable_stats.values())
    memory_size = int(df.memory_usage(index=True, deep=config.memory_deep).sum())
    return {
        "n": n,
        "n_var": n_var,
        "memory_size": memory_size,
        "record_size": float(memory_size / max(n, 1)),
        "n_cells_missing": n_missing,
        "p_cells_missing": float(n_missing / max(n * max(n_var, 1), 1)),
        "types": dict(types),
    }


@get_time_index_description.register
def pandas_get_time_index_description(
    config: Settings,
    df: pd.DataFrame,
    table_stats: dict,
) -> dict:
    index = df.index
    if not isinstance(index, (pd.DatetimeIndex, pd.RangeIndex, pd.Index)):
        return {}
    if len(index) == 0:
        return {}
    frequency = getattr(index, "freqstr", None)
    period = index[-1] - index[0] if len(index) > 1 else 0
    return {
        "n_series": int(len(df.columns)),
        "length": int(len(index)),
        "start": index[0],
        "end": index[-1],
        "period": period,
        "frequency": frequency,
    }


def _numeric_columns(summary: dict) -> List[str]:
    return [name for name, desc in summary.items() if desc.get("type") in {"Numeric", "TimeSeries"}]


def _categorical_columns(summary: dict) -> List[str]:
    return [name for name, desc in summary.items() if desc.get("type") in {"Categorical", "Boolean", "Text"}]


def _pairwise_spearman(col_1: pd.Series, col_2: pd.Series) -> float:
    return float(col_1.corr(col_2, method="spearman"))


def _cramers_corrected_stat(confusion_matrix: pd.DataFrame, correction: bool) -> float:
    if confusion_matrix.empty:
        return 0.0
    chi2 = stats.chi2_contingency(confusion_matrix, correction=correction)[0]
    n = confusion_matrix.to_numpy().sum()
    if n == 0:
        return 0.0
    phi2 = chi2 / n
    r, k = confusion_matrix.shape
    phi2corr = max(0, phi2 - ((k - 1) * (r - 1)) / max(n - 1, 1))
    rcorr = r - ((r - 1) ** 2) / max(n - 1, 1)
    kcorr = k - ((k - 1) ** 2) / max(n - 1, 1)
    denominator = min(kcorr - 1, rcorr - 1)
    if denominator <= 0:
        return 0.0
    return float(np.sqrt(phi2corr / denominator))


def _pairwise_cramers(col_1: pd.Series, col_2: pd.Series) -> float:
    confusion = pd.crosstab(col_1.fillna("<NA>"), col_2.fillna("<NA>"))
    return _cramers_corrected_stat(confusion, correction=True)


def pearson_compute(config: Settings, df: pd.DataFrame, summary: dict) -> Optional[pd.DataFrame]:
    cols = _numeric_columns(summary)
    return df[cols].corr(method="pearson") if len(cols) >= 2 else None


def spearman_compute(config: Settings, df: pd.DataFrame, summary: dict) -> Optional[pd.DataFrame]:
    cols = _numeric_columns(summary)
    return df[cols].corr(method="spearman") if len(cols) >= 2 else None


def kendall_compute(config: Settings, df: pd.DataFrame, summary: dict) -> Optional[pd.DataFrame]:
    cols = _numeric_columns(summary)
    return df[cols].corr(method="kendall") if len(cols) >= 2 else None


def cramers_compute(config: Settings, df: pd.DataFrame, summary: dict) -> Optional[pd.DataFrame]:
    cols = _categorical_columns(summary)
    if len(cols) < 2:
        return None
    matrix = pd.DataFrame(index=cols, columns=cols, dtype=float)
    for col_a in cols:
        for col_b in cols:
            matrix.loc[col_a, col_b] = 1.0 if col_a == col_b else _pairwise_cramers(df[col_a], df[col_b])
    return matrix


def phik_compute(config: Settings, df: pd.DataFrame, summary: dict) -> Optional[pd.DataFrame]:
    try:
        import phik  # noqa: F401
    except Exception:
        return auto_compute(config, df, summary)
    cols = [name for name, desc in summary.items() if desc.get("n_distinct", 0) <= config.categorical_maximum_correlation_distinct]
    if len(cols) < 2:
        return None
    try:
        return df[cols].phik_matrix(interval_cols=_numeric_columns(summary))
    except Exception:
        return auto_compute(config, df, summary)


def auto_compute(config: Settings, df: pd.DataFrame, summary: dict) -> Optional[pd.DataFrame]:
    return pearson_compute(config, df, summary) or spearman_compute(config, df, summary)


def missing_bar(config: Settings, df: pd.DataFrame) -> str:
    counts = df.notna().sum().tolist()
    return plot_missing_bar(config, counts, len(df), list(df.columns))


def missing_matrix(config: Settings, df: pd.DataFrame) -> str:
    return plot_missing_matrix(config, df.notna(), list(df.columns), len(df))


def missing_heatmap(config: Settings, df: pd.DataFrame) -> str:
    corr = df.isna().corr()
    mask = np.triu(np.ones_like(corr, dtype=bool))
    return plot_missing_heatmap(config, corr, mask, list(df.columns))

