"""Type inference helpers."""

from __future__ import annotations

from pathlib import Path
from typing import Dict, Optional, Set
from urllib.parse import urlparse

import pandas as pd

try:
    from visions import VisionsTypeset
    from visions.typesets import StandardSet
except Exception:  # pragma: no cover
    class VisionsTypeset:  # type: ignore
        pass

    class StandardSet(VisionsTypeset):  # type: ignore
        def __init__(self, *args, **kwargs):
            pass


class Generic:
    pass


class Unsupported:
    pass


class Numeric:
    pass


class Complex:
    pass


class Text:
    pass


class DateTime:
    pass


class Categorical:
    pass


class Boolean:
    pass


class URL:
    pass


class PathType:
    pass


class File:
    pass


class Image:
    pass


class TimeSeries:
    pass


TYPE_REGISTRY = {
    "Generic": Generic,
    "Unsupported": Unsupported,
    "Numeric": Numeric,
    "Complex": Complex,
    "Text": Text,
    "DateTime": DateTime,
    "Categorical": Categorical,
    "Boolean": Boolean,
    "URL": URL,
    "Path": PathType,
    "File": File,
    "Image": Image,
    "TimeSeries": TimeSeries,
}


def typeset_types(config) -> Set[type]:
    return set(TYPE_REGISTRY.values())


class ProfilingTypeSet(StandardSet):
    def __init__(self, config, type_schema: dict = None):
        try:
            super().__init__()
        except Exception:
            pass
        self.config = config
        self.type_schema = self._init_type_schema(type_schema or {})
        self.type_hierarchy: Dict[str, list[str]] = {
            "Unsupported": ["Generic"],
            "Numeric": ["Generic"],
            "Complex": ["Generic"],
            "Text": ["Generic"],
            "DateTime": ["Generic"],
            "Categorical": ["Text"],
            "Boolean": ["Categorical"],
            "URL": ["Text"],
            "Path": ["Text"],
            "File": ["Path"],
            "Image": ["File"],
            "TimeSeries": ["Numeric"],
            "Integer": ["Numeric"],
            "Float": ["Numeric"],
        }

    def _init_type_schema(self, type_schema: dict) -> dict:
        return {str(key): self._get_type(value) if isinstance(value, str) else value for key, value in type_schema.items()}

    def _get_type(self, type_name: str):
        return TYPE_REGISTRY.get(type_name, TYPE_REGISTRY["Unsupported"])

    def _looks_url(self, series: pd.Series) -> bool:
        try:
            parsed = series.astype(str).map(urlparse)
            return parsed.map(lambda item: bool(item.scheme and item.netloc)).all()
        except Exception:
            return False

    def _looks_path(self, series: pd.Series) -> bool:
        return series.astype(str).map(lambda value: "/" in value or "\\" in value).all()

    def _looks_file(self, series: pd.Series) -> bool:
        return series.astype(str).map(lambda value: Path(value).suffix != "").all()

    def _looks_image(self, series: pd.Series) -> bool:
        image_exts = {".png", ".jpg", ".jpeg", ".gif", ".bmp", ".webp", ".tiff", ".svg"}
        return series.astype(str).map(lambda value: Path(value).suffix.lower() in image_exts).all()

    def infer_series_type(self, series: pd.Series, column_name: Optional[str] = None, tsmode: bool = False):
        if column_name is not None and column_name in self.type_schema:
            return self.type_schema[column_name]

        non_null = series.dropna()
        if pd.api.types.is_bool_dtype(series):
            return Boolean
        if pd.api.types.is_complex_dtype(series):
            return Complex
        if pd.api.types.is_datetime64_any_dtype(series):
            return DateTime
        if pd.api.types.is_numeric_dtype(series):
            return TimeSeries if (tsmode or self.config.vars.timeseries.active) else Numeric

        if non_null.empty:
            return Unsupported

        lowered = non_null.astype(str).str.lower()
        if lowered.isin(self.config.vars.bool.mappings.keys()).all():
            return Boolean
        if self.config.vars.url.active and self._looks_url(non_null):
            return URL
        if self.config.vars.image.active and self._looks_image(non_null):
            return Image
        if self.config.vars.file.active and self._looks_file(non_null):
            return File
        if self.config.vars.path.active and self._looks_path(non_null):
            return PathType
        if self.config.vars.cat.coerce_str_to_date:
            converted = pd.to_datetime(non_null, errors="coerce")
            if converted.notna().all():
                return DateTime
        n = max(len(non_null), 1)
        n_unique = non_null.nunique(dropna=True)
        if (
            n_unique <= self.config.vars.cat.cardinality_threshold
            and (n_unique / n) <= self.config.vars.cat.percentage_cat_threshold
        ):
            return Categorical
        return Text

    def infer_type_name(self, series: pd.Series, column_name: Optional[str] = None, tsmode: bool = False) -> str:
        return self.infer_series_type(series, column_name, tsmode).__name__.replace("PathType", "Path")

