"""Shared summary algorithms and multimethod declarations."""

from __future__ import annotations

import functools
import math
from typing import Any, Callable, Dict, Optional, Tuple

import numpy as np
import pandas as pd
from multimethod import multimethod
from scipy import stats
from scipy.fft import fft
from scipy.signal import find_peaks
from statsmodels.tsa.stattools import adfuller

from ydata_profiling.config import Settings


def func_nullable_series_contains(fn: Callable) -> Callable:
    @functools.wraps(fn)
    def inner(config: Settings, series: pd.Series, state: dict, *args, **kwargs) -> bool:
        if getattr(series, "hasnans", False):
            series = series.dropna()
        if series.empty:
            return False
        return bool(fn(config, series, state, *args, **kwargs))

    return inner


def series_hashable(
    fn: Callable[[Settings, pd.Series, dict], Tuple[Settings, pd.Series, dict]]
) -> Callable[[Settings, pd.Series, dict], Tuple[Settings, pd.Series, dict]]:
    @functools.wraps(fn)
    def inner(config: Settings, series: pd.Series, summary: dict):
        if not summary.get("hashable", True):
            return config, series, summary
        return fn(config, series, summary)

    return inner


def series_handle_nulls(
    fn: Callable[[Settings, pd.Series, dict], Tuple[Settings, pd.Series, dict]]
) -> Callable[[Settings, pd.Series, dict], Tuple[Settings, pd.Series, dict]]:
    @functools.wraps(fn)
    def inner(config: Settings, series: pd.Series, summary: dict):
        if getattr(series, "hasnans", False):
            series = series.dropna()
        return fn(config, series, summary)

    return inner


def chi_square(
    values: Optional[np.ndarray] = None, histogram: Optional[np.ndarray] = None
) -> dict:
    if histogram is None:
        if values is None or len(values) == 0:
            return {"statistic": 0.0, "pvalue": 0.0}
        bins = np.histogram_bin_edges(values, bins="auto")
        histogram = np.histogram(values, bins=bins)[0]
    if histogram.size == 0 or histogram.sum() == 0:
        return {"statistic": 0.0, "pvalue": 0.0}
    result = stats.chisquare(histogram)
    return {"statistic": float(result.statistic), "pvalue": float(result.pvalue)}


def mad(arr: np.ndarray) -> np.ndarray:
    median = np.median(arr)
    return np.median(np.abs(arr - median))


def numeric_stats_pandas(series: pd.Series) -> Dict[str, Any]:
    return {
        "mean": float(series.mean()),
        "std": float(series.std()),
        "variance": float(series.var()),
        "min": float(series.min()),
        "max": float(series.max()),
        "kurtosis": float(series.kurt()),
        "skewness": float(series.skew()),
        "sum": float(series.sum()),
    }


def numeric_stats_numpy(
    present_values: np.ndarray, series: pd.Series, series_description: Dict[str, Any]
) -> Dict[str, Any]:
    if present_values.size == 0:
        return {
            "mean": math.nan,
            "std": math.nan,
            "variance": math.nan,
            "min": math.nan,
            "max": math.nan,
            "kurtosis": math.nan,
            "skewness": math.nan,
            "sum": 0.0,
        }
    return {
        "mean": float(np.mean(present_values)),
        "std": float(np.std(present_values, ddof=1)) if present_values.size > 1 else 0.0,
        "variance": float(np.var(present_values, ddof=1)) if present_values.size > 1 else 0.0,
        "min": float(np.min(present_values)),
        "max": float(np.max(present_values)),
        "kurtosis": float(series.kurt()),
        "skewness": float(series.skew()),
        "sum": float(np.sum(present_values)),
    }


def named_aggregate_summary(series: pd.Series, key: str) -> dict:
    return {
        f"max_{key}": float(np.max(series)) if len(series) else 0.0,
        f"mean_{key}": float(np.mean(series)) if len(series) else 0.0,
        f"median_{key}": float(np.median(series)) if len(series) else 0.0,
        f"min_{key}": float(np.min(series)) if len(series) else 0.0,
    }


def histogram_compute(
    config: Settings,
    finite_values: np.ndarray,
    n_unique: int,
    name: str = "histogram",
    weights: Optional[np.ndarray] = None,
) -> dict:
    if finite_values.size == 0:
        return {name: {"counts": [], "bin_edges": []}}
    bins = config.plot.histogram.bins or min(config.plot.histogram.max_bins, max(1, n_unique))
    counts, edges = np.histogram(finite_values, bins=bins, weights=weights)
    return {name: {"counts": counts.tolist(), "bin_edges": edges.tolist()}}


def stationarity_test(config: Settings, series: pd.Series) -> Tuple[bool, float]:
    clean = series.dropna()
    if len(clean) < 3:
        return True, 1.0
    _, pvalue, *_ = adfuller(
        clean,
        autolag=config.vars.timeseries.autolag,
        maxlag=config.vars.timeseries.maxlag,
    )
    return pvalue < config.vars.timeseries.significance, float(pvalue)


def fftfreq(n: int, d: float = 1.0) -> np.ndarray:
    values = np.empty(n, dtype=float)
    half = (n - 1) // 2 + 1
    values[:half] = np.arange(0, half)
    values[half:] = np.arange(-(n // 2), 0)
    return values / (n * d)


def get_fft(series: pd.Series) -> pd.DataFrame:
    transformed = fft(series.to_numpy())
    power = np.abs(transformed) ** 2
    freq = fftfreq(len(power), 1.0)
    mask = freq > 0
    return pd.DataFrame({"freq": freq[mask], "ampl": 10 * np.log10(power[mask] + 1e-12)})


def get_fft_peaks(
    fft_df: pd.DataFrame, mad_threshold: float = 6.0
) -> Tuple[float, pd.DataFrame, pd.DataFrame]:
    if fft_df.empty:
        return 0.0, fft_df, fft_df
    positive = fft_df[fft_df["ampl"] > 0]
    if positive.empty:
        return 0.0, positive, positive
    median = float(positive["ampl"].median())
    amplitude_deviation = mad(positive["ampl"].to_numpy())
    threshold = median + amplitude_deviation * mad_threshold
    peak_idx, _ = find_peaks(positive["ampl"].to_numpy())
    peaks = positive.iloc[peak_idx].copy()
    selected = peaks[peaks["ampl"] >= threshold].copy()
    filtered_rows = []
    selected_freqs = []
    for _, row in selected.sort_values("freq").iterrows():
        freq = float(row["freq"])
        if any(abs((freq / base) - round(freq / base)) < 0.01 for base in selected_freqs if base):
            continue
        selected_freqs.append(freq)
        filtered_rows.append(row)
    selected = pd.DataFrame(filtered_rows) if filtered_rows else selected.iloc[0:0]
    return threshold, peaks, selected


def seasonality_test(series: pd.Series, mad_threshold: float = 6.0) -> Dict[str, Any]:
    clean = series.dropna()
    if len(clean) < 4:
        return {"seasonality_presence": False, "seasonalities": []}
    fft_df = get_fft(clean)
    _, peaks, selected = get_fft_peaks(fft_df, mad_threshold)
    seasonalities = [float(1 / freq) for freq in selected["freq"].tolist() if freq]
    return {
        "seasonality_presence": not selected.empty,
        "seasonalities": seasonalities,
        "fft": fft_df,
        "fft_peaks": peaks,
        "fft_selected_peaks": selected,
    }


