"""Plot functions for the profiling report."""

from __future__ import annotations

import base64
import io
from datetime import timedelta
from typing import Any, List, Optional, Tuple, Union

import matplotlib.dates as mdates
import matplotlib.pyplot as plt
import numpy as np
import pandas as pd
import seaborn as sns
from matplotlib.artist import Artist
from matplotlib.colors import Colormap, LinearSegmentedColormap, ListedColormap, to_hex
from matplotlib.ticker import FuncFormatter
from scipy import stats
from statsmodels.graphics.tsaplots import plot_acf, plot_pacf

from ydata_profiling.visualisation.context import manage_matplotlib_context
from ydata_profiling.visualisation.missing import get_font_size
from ydata_profiling.utils.common import convert_timestamp_to_datetime

try:
    from wordcloud import WordCloud
except Exception:  # pragma: no cover
    WordCloud = None


def hex_to_rgb(value: str) -> Tuple[float, ...]:
    value = value.lstrip("#")
    step = len(value) // 3
    return tuple(int(value[i : i + step], 16) / 255.0 for i in range(0, len(value), step))


def base64_image(image: bytes, mime_type: str) -> str:
    return f"data:{mime_type};base64,{base64.b64encode(image).decode('ascii')}"


def _figure_to_b64(
    config,
    image_format: Optional[str] = None,
    bbox_extra_artists: Optional[List[Artist]] = None,
    bbox_inches: Optional[str] = None,
) -> str:
    fmt = image_format or getattr(config.plot.image_format, "value", str(config.plot.image_format))
    fmt = "svg" if fmt == "svg" else "png"
    buffer = io.BytesIO()
    kwargs = {}
    if bbox_extra_artists is not None:
        kwargs["bbox_extra_artists"] = bbox_extra_artists
    if bbox_inches is not None:
        kwargs["bbox_inches"] = bbox_inches
    plt.savefig(buffer, format=fmt, dpi=config.plot.dpi if fmt == "png" else None, **kwargs)
    return base64_image(buffer.getvalue(), f"image/{fmt}")


def format_fn(tick_val: int, tick_pos: Any) -> str:
    return convert_timestamp_to_datetime(int(tick_val)).strftime("%Y-%m-%d %H:%M:%S")


def create_comparison_color_list(config) -> List[str]:
    colors = list(config.html.style.primary_colors)
    labels = getattr(config.html.style, "_labels", ["_"])
    if len(colors) >= len(labels):
        return colors[: len(labels)]
    cmap = LinearSegmentedColormap.from_list("comparison", colors or ["#0d6efd", "#dc3545"])
    return [to_hex(cmap(i / max(len(labels) - 1, 1))) for i in range(len(labels))]


def get_cmap_half(
    cmap: Union[Colormap, LinearSegmentedColormap, ListedColormap]
) -> LinearSegmentedColormap:
    colors = cmap(np.linspace(0.5, 1, max(cmap.N // 2, 2)))
    return LinearSegmentedColormap.from_list(f"{cmap.name}_half", colors)


def get_correlation_font_size(n_labels: int) -> Optional[int]:
    if n_labels > 100:
        return 4
    if n_labels > 80:
        return 5
    if n_labels > 50:
        return 6
    if n_labels > 40:
        return 8
    return None


def _set_visibility(axis, tick_mark: str = "none"):
    for side in ("top", "right", "bottom", "left"):
        axis.spines[side].set_visible(False)
    axis.xaxis.set_ticks_position(tick_mark)
    axis.yaxis.set_ticks_position(tick_mark)
    return axis


def _format_ts_date_axis(series: pd.Series, axis):
    if isinstance(series.index, pd.DatetimeIndex):
        locator = mdates.AutoDateLocator()
        axis.xaxis.set_major_locator(locator)
        axis.xaxis.set_major_formatter(mdates.ConciseDateFormatter(locator))
    return axis


def _plot_histogram(
    config,
    series: np.ndarray,
    bins: Union[int, np.ndarray],
    figsize: tuple = (6, 4),
    date: bool = False,
    hide_yaxis: bool = False,
) -> plt.Figure:
    fig, ax = plt.subplots(figsize=figsize)
    if isinstance(series, list):
        colors = create_comparison_color_list(config)
        labels = getattr(config.html.style, "_labels", [f"Series {i+1}" for i in range(len(series))])
        for values, color, label in zip(series, colors, labels):
            ax.hist(values, bins=bins, alpha=0.45, color=color, label=label, density=config.plot.histogram.density)
        ax.legend()
    else:
        ax.hist(series, bins=bins, color=config.html.style.primary_color, density=config.plot.histogram.density)
    if date:
        ax.xaxis.set_major_formatter(FuncFormatter(format_fn))
    if hide_yaxis:
        ax.set_yticks([])
    if not config.plot.histogram.x_axis_labels:
        ax.set_xticks([])
    fig.tight_layout()
    return fig


def _plot_word_cloud(config, series: Union[pd.Series, List[pd.Series]], figsize: tuple = (6, 4)) -> plt.Figure:
    values = series if isinstance(series, list) else [series]
    fig, axes = plt.subplots(1, len(values), figsize=(figsize[0] * len(values), figsize[1]))
    if len(values) == 1:
        axes = [axes]
    for ax, freq in zip(axes, values):
        ax.axis("off")
        if WordCloud is None:
            ax.text(0.5, 0.5, "wordcloud unavailable", ha="center", va="center")
            continue
        cloud = WordCloud(
            background_color="white",
            width=600,
            height=400,
            random_state=42,
            font_path=config.plot.font_path,
        ).generate_from_frequencies(freq.to_dict())
        ax.imshow(cloud, interpolation="bilinear")
    fig.tight_layout()
    return fig


def _plot_pie_chart(data: pd.Series, colors: List, hide_legend: bool = False):
    fig, ax = plt.subplots(figsize=(6, 4))
    wedges, texts, autotexts = ax.pie(data.values, labels=None if hide_legend else data.index, colors=colors, autopct="%1.1f%%")
    legend = None if hide_legend else ax.legend(wedges, list(data.index), bbox_to_anchor=(1.0, 0.5), loc="center left")
    return ax, legend


def _plot_stacked_barh(data: pd.Series, colors: List, hide_legend: bool = False):
    fig, ax = plt.subplots(figsize=(6, 1.8))
    total = max(data.sum(), 1)
    left = 0.0
    for idx, (label, value) in enumerate(data.items()):
        width = value / total
        ax.barh([0], [width], left=left, color=colors[idx % len(colors)], label=label)
        left += width
    legend = None if hide_legend else ax.legend(bbox_to_anchor=(1.0, 0.5), loc="center left")
    _set_visibility(ax)
    return ax, legend


def _prepare_heatmap_data(
    dataframe: pd.DataFrame,
    entity_column: str,
    sortby: Optional[Union[str, list]] = None,
    max_entities: int = 5,
    selected_entities: Optional[List[str]] = None,
) -> pd.DataFrame:
    if selected_entities is None:
        entities = dataframe[entity_column].value_counts().head(max_entities).index.tolist()
    else:
        entities = selected_entities
    subset = dataframe[dataframe[entity_column].isin(entities)].copy()
    if sortby is not None:
        subset = subset.sort_values(sortby)
    return subset


def _create_timeseries_heatmap(
    df: pd.DataFrame,
    figsize: Tuple[int, int] = (12, 5),
    color: str = "#337ab7",
):
    fig, ax = plt.subplots(figsize=figsize)
    sns.heatmap(df, cmap=sns.light_palette(color, as_cmap=True), ax=ax)
    return ax


@manage_matplotlib_context()
def plot_word_cloud(config, word_counts: pd.Series) -> str:
    _plot_word_cloud(config, word_counts)
    return _figure_to_b64(config)


@manage_matplotlib_context()
def histogram(config, series: np.ndarray, bins: Union[int, np.ndarray], date: bool = False) -> str:
    _plot_histogram(config, series, bins, figsize=(7, 3), date=date)
    return _figure_to_b64(config)


@manage_matplotlib_context()
def mini_histogram(config, series: np.ndarray, bins: Union[int, np.ndarray], date: bool = False) -> str:
    _plot_histogram(config, series, bins, figsize=(3, 2.25), date=date, hide_yaxis=True)
    return _figure_to_b64(config)


@manage_matplotlib_context()
def correlation_matrix(config, data: pd.DataFrame, vmin: int = -1) -> str:
    fig, ax = plt.subplots(figsize=(6, 5))
    sns.heatmap(
        data,
        cmap=config.plot.correlation.cmap,
        vmin=vmin,
        vmax=1,
        center=0,
        ax=ax,
        square=True,
        cbar=True,
    )
    font_size = get_correlation_font_size(len(data.columns))
    if font_size is not None:
        ax.tick_params(labelsize=font_size)
    fig.tight_layout()
    return _figure_to_b64(config)


@manage_matplotlib_context()
def scatter_complex(config, series: pd.Series) -> str:
    fig, ax = plt.subplots(figsize=(5, 4))
    ax.scatter(series.map(np.real), series.map(np.imag), color=config.html.style.primary_color)
    ax.set_xlabel("Real")
    ax.set_ylabel("Imaginary")
    fig.tight_layout()
    return _figure_to_b64(config)


@manage_matplotlib_context()
def scatter_series(config, series: pd.Series, x_label: str = "Width", y_label: str = "Height") -> str:
    fig, ax = plt.subplots(figsize=(5, 4))
    coords = list(series.dropna())
    if coords:
        x, y = zip(*coords)
        ax.scatter(x, y, color=config.html.style.primary_color)
    ax.set_xlabel(x_label)
    ax.set_ylabel(y_label)
    fig.tight_layout()
    return _figure_to_b64(config)


@manage_matplotlib_context()
def scatter_pairwise(config, series1: pd.Series, series2: pd.Series, x_label: str, y_label: str) -> str:
    fig, ax = plt.subplots(figsize=(5, 4))
    aligned = pd.concat([series1, series2], axis=1).dropna()
    ax.scatter(aligned.iloc[:, 0], aligned.iloc[:, 1], color=config.html.style.primary_color, alpha=0.7)
    ax.set_xlabel(x_label)
    ax.set_ylabel(y_label)
    fig.tight_layout()
    return _figure_to_b64(config)


@manage_matplotlib_context()
def cat_frequency_plot(config, series: pd.Series) -> str:
    data = series.value_counts().head(config.plot.cat_freq.max_unique)
    colors = config.plot.cat_freq.colors or create_comparison_color_list(config)
    if config.plot.cat_freq.type == "pie":
        _plot_pie_chart(data, colors)
    else:
        _plot_stacked_barh(data, colors)
    return _figure_to_b64(config)


def missing_bar(
    notnull_counts: pd.Series,
    nrows: int,
    figsize: Tuple[float, float] = (25, 10),
    fontsize: float = 16,
    labels: bool = True,
    color: Tuple[float, ...] = (0.41, 0.41, 0.41),
    label_rotation: int = 45,
):
    fig, ax = plt.subplots(figsize=figsize)
    missing = nrows - notnull_counts
    ax.bar(range(len(notnull_counts)), missing, color=color)
    if labels:
        ax.set_xticks(range(len(notnull_counts)))
        ax.set_xticklabels(list(notnull_counts.index), rotation=label_rotation, ha="right", fontsize=fontsize)
    return ax


def missing_heatmap(
    corr_mat: Any,
    mask: Any,
    figsize: Tuple[float, float] = (20, 12),
    fontsize: float = 16,
    labels: bool = True,
    label_rotation: int = 45,
    cmap: str = "RdBu",
    normalized_cmap: bool = True,
    cbar: bool = True,
    ax=None,
):
    if ax is None:
        fig, ax = plt.subplots(figsize=figsize)
    sns.heatmap(corr_mat, mask=mask, cmap=cmap, cbar=cbar, ax=ax, center=0)
    if labels:
        ax.set_xticklabels(ax.get_xticklabels(), rotation=label_rotation, ha="right", fontsize=fontsize)
        ax.set_yticklabels(ax.get_yticklabels(), fontsize=fontsize)
    return ax


@manage_matplotlib_context()
def plot_missing_matrix(config, notnull: Any, columns: List[str], nrows: int) -> str:
    fig, ax = plt.subplots(figsize=(min(25, max(6, len(columns) * 0.6)), 6))
    ax.imshow(np.asarray(notnull).T, aspect="auto", interpolation="nearest", cmap="gray_r")
    ax.set_yticks(range(len(columns)))
    ax.set_yticklabels(columns, fontsize=get_font_size(columns))
    ax.set_xlabel("Rows")
    ax.set_title("Missing matrix")
    fig.tight_layout()
    return _figure_to_b64(config)


@manage_matplotlib_context()
def plot_missing_bar(config, notnull_counts: list, nrows: int, columns: List[str]) -> str:
    series = pd.Series(notnull_counts, index=columns)
    missing_bar(
        series,
        nrows,
        figsize=(min(25, max(6, len(columns) * 0.6)), 5),
        fontsize=get_font_size(columns),
        labels=True,
        color=hex_to_rgb(config.html.style.primary_color),
    )
    plt.tight_layout()
    return _figure_to_b64(config)


@manage_matplotlib_context()
def plot_missing_heatmap(config, corr_mat: Any, mask: Any, columns: List[str]) -> str:
    missing_heatmap(
        corr_mat,
        mask,
        figsize=(min(20, max(6, len(columns) * 0.8)), min(12, max(4, len(columns) * 0.6))),
        fontsize=get_font_size(columns),
        cmap=config.plot.correlation.cmap,
    )
    plt.tight_layout()
