def _plot_timeseries(config, series: Union[list, pd.Series], figsize: tuple = (6, 4)):
    fig, ax = plt.subplots(figsize=figsize)
    if isinstance(series, list):
        colors = create_comparison_color_list(config)
        labels = getattr(config.html.style, "_labels", [f"Series {i+1}" for i in range(len(series))])
