"""Frequency table helpers."""

from __future__ import annotations

from typing import Any, Dict, List, Union

import pandas as pd


def _frequency_table(
    freqtable: pd.Series, n: int, max_number_to_print: int
) -> List[Dict[str, Any]]:
    if freqtable.empty:
        return []
    rows = []
    max_freq = max(int(freqtable.max()), 1)
    shown = freqtable.iloc[:max_number_to_print]
    for label, count in shown.items():
        rows.append(
            {
                "label": label,
                "width": float(count / max_freq),
                "count": int(count),
                "percentage": float(count / max(n, 1)),
                "n": n,
                "extra_class": "",
            }
        )
    other = int(freqtable.iloc[max_number_to_print:].sum()) if len(freqtable) > max_number_to_print else 0
    if other:
        rows.append(
            {
                "label": "Other values",
                "width": float(other / max_freq),
                "count": other,
                "percentage": float(other / max(n, 1)),
                "n": n,
                "extra_class": "other",
            }
        )
    return rows


def freq_table(
    freqtable: Union[pd.Series, List[pd.Series]],
    n: Union[int, List[int]],
    max_number_to_print: int,
) -> Union[List[Dict[str, Any]], List[List[Dict[str, Any]]]]:
    if isinstance(freqtable, list):
        counts = n if isinstance(n, list) else [n] * len(freqtable)
        return [_frequency_table(ft, count, max_number_to_print) for ft, count in zip(freqtable, counts)]
    return _frequency_table(freqtable, int(n), max_number_to_print)


