    for label, count in freqtable.iloc[:number_to_print].items():
        rows.append(
            {
                "label": label,
                "width": float(count / max_freq),
                "count": int(count),
                "percentage": float(count / max(n, 1)),
                "n": n,
                "extra_class": "",
            }
        )
    return rows


