"""Formatters are mappings from object(s) to a string."""

from __future__ import annotations

import html
import math
import re
from datetime import timedelta
from typing import Any, Callable, List, Optional, Union

import numpy as np


def list_args(func: Callable) -> Callable:
    def inner(arg: Any, *args: Any, **kwargs: Any) -> Any:
        if isinstance(arg, list):
            return [func(item, *args, **kwargs) for item in arg]
        return func(arg, *args, **kwargs)

    return inner


@list_args
def fmt_color(text: str, color: str) -> str:
    return f'<span style="color:{html.escape(color)}">{html.escape(str(text))}</span>'


@list_args
def fmt_class(text: str, cls: str) -> str:
    return f'<span class="{html.escape(cls)}">{html.escape(str(text))}</span>'


@list_args
def fmt_bytesize(num: float, suffix: str = "B") -> str:
    num = float(num)
    units = ["", "Ki", "Mi", "Gi", "Ti", "Pi"]
    for unit in units:
        if abs(num) < 1024.0:
            return f"{num:3.1f} {unit}{suffix}"
        num /= 1024.0
    return f"{num:.1f} Ei{suffix}"


@list_args
def fmt_percent(value: float, edge_cases: bool = True) -> str:
    if edge_cases and value in {0, 1}:
        return f"{value * 100:.1f}%"
    return f"{value * 100:.1f}%"


def remove_suffix(text: str, suffix: str) -> str:
    return text[: -len(suffix)] if suffix and text.endswith(suffix) else text


@list_args
def fmt_timespan(num_seconds: Any, detailed: bool = False, max_units: int = 3) -> str:
    def round_number(count: Any, keep_width: bool = False) -> str:
        text = f"{float(count):.2f}"
        return text if keep_width else re.sub(r"\.?0+$", "", text)

    def coerce_seconds(value: Union[timedelta, int, float]) -> float:
        if isinstance(value, timedelta):
            return value.total_seconds()
        return float(value)

    def concatenate(items: List[str]) -> str:
        if not items:
            return ""
        if len(items) == 1:
            return items[0]
        return ", ".join(items[:-1]) + f" and {items[-1]}"

    def pluralize(count: Any, singular: str, plural: Optional[str] = None) -> str:
        plural = plural or f"{singular}s"
        return f"{round_number(count)} {singular if math.floor(float(count)) == 1 else plural}"

    seconds = abs(coerce_seconds(num_seconds))
    units = [
        ("week", 604800),
        ("day", 86400),
        ("hour", 3600),
        ("minute", 60),
        ("second", 1),
        ("millisecond", 1e-3),
        ("microsecond", 1e-6),
        ("nanosecond", 1e-9),
    ]
    values = []
    remaining = seconds
    for name, size in units:
        if remaining >= size or (detailed and size < 1 and remaining > 0):
            count = remaining / size if size < 1 else int(remaining // size)
            values.append(pluralize(count, name))
            if size >= 1:
                remaining %= size
            if len(values) >= max_units:
                break
    return concatenate(values) or "0 seconds"


@list_args
def fmt_timespan_timedelta(
    delta: Any, detailed: bool = False, max_units: int = 3, precision: int = 10
) -> str:
    return fmt_timespan(delta, detailed=detailed, max_units=max_units)


@list_args
def fmt_numeric(value: float, precision: int = 10) -> str:
    if value is None or (isinstance(value, float) and math.isnan(value)):
        return "nan"
    text = f"{float(value):.{precision}g}"
    text = text.replace("e+", " × 10<sup>").replace("e-", " × 10<sup>-")
    if "<sup>" in text and not text.endswith("</sup>"):
        text += "</sup>"
    return text


@list_args
def fmt_number(value: int) -> str:
    return f"{int(value):n}"


@list_args
def fmt_array(value: np.ndarray, threshold: Any = np.nan) -> str:
    with np.printoptions(threshold=3 if np.isnan(threshold) else threshold):
        return np.array2string(np.asarray(value))


@list_args
def fmt_monotonic(value: int) -> str:
    mapping = {
        -2: "Strictly decreasing",
        -1: "Decreasing",
        0: "Not monotonic",
        1: "Increasing",
        2: "Strictly increasing",
    }
    if value not in mapping:
        raise ValueError(value)
    return mapping[value]


@list_args
def fmt_badge(value: str) -> str:
    value = html.escape(str(value))
    return re.sub(r"\((\d+)\)", r'<span class="badge bg-secondary">\1</span>', value)

