"""HTML flavour renderers."""

from __future__ import annotations

from html import escape

import pandas as pd

from ydata_profiling.report.presentation.core import (
    Alerts,
    Collapse,
    Container,
    CorrelationTable,
    Dropdown,
    Duplicate,
    FrequencyTable,
    FrequencyTableSmall,
    HTML,
    Image,
    Root,
    Sample,
    Scores,
    Table,
    ToggleButton,
    Variable,
    VariableInfo,
)
from ydata_profiling.report.presentation.flavours.html.templates import template
from ydata_profiling.utils.styles import get_alert_styles


def _render_rows(rows) -> str:
    fragments = []
    for row in rows:
        label = escape(str(row.get("label", "")))
        count = escape(str(row.get("count", "")))
        percentage = f"{row.get('percentage', 0) * 100:.1f}%"
        width = f"{row.get('width', 0) * 100:.1f}%"
        extra = row.get("extra_class", "")
        fragments.append(
            f'<div class="freq-row {escape(extra)}"><strong>{label}</strong> '
            f'<span>{count}</span> <span>{percentage}</span>'
            f'<div style="background:#0d6efd33;height:.5rem;width:{width}"></div></div>'
        )
    return "".join(fragments)


def _table_to_html(rows) -> str:
    if isinstance(rows, pd.DataFrame):
        return rows.to_html(index=False, escape=False)
    if not rows:
        return "<table></table>"
    if isinstance(rows[0], dict):
        headers = list(rows[0].keys())
        head = "".join(f"<th>{escape(str(h))}</th>" for h in headers)
        body = []
        for row in rows:
            body.append("<tr>" + "".join(f"<td>{escape(str(row.get(h, '')))}</td>" for h in headers) + "</tr>")
        return f"<table><thead><tr>{head}</tr></thead><tbody>{''.join(body)}</tbody></table>"
    body = []
    for row in rows:
        if isinstance(row, (list, tuple)) and len(row) == 2:
            body.append(f"<tr><th>{escape(str(row[0]))}</th><td>{row[1]}</td></tr>")
    return f"<table><tbody>{''.join(body)}</tbody></table>"


class HTMLAlerts(Alerts):
    def render(self) -> str:
        alerts = self.content["alerts"]
        if isinstance(alerts, dict):
            flat = [item for items in alerts.values() for item in items]
        else:
            flat = list(alerts)
        styles = get_alert_styles()
        body = "".join(
            f'<div class="alert alert-{styles.get(alert.alert_type_name, "secondary")}">{escape(alert.fmt())}</div>'
            for alert in flat
        )
        return template("alerts.html").render(body=body)


class HTMLCollapse(Collapse):
    def render(self) -> str:
        return template("collapse.html").render(button=self.content["button"].render(), item=self.content["item"].render())


class HTMLContainer(Container):
    def render(self) -> str:
        items = "".join(item.render() for item in self.content["items"])
        template_name = {
            "list": "sequence/list.html",
            "named_list": "sequence/named_list.html",
            "tabs": "sequence/tabs.html",
            "sections": "sequence/sections.html",
            "select": "sequence/select.html",
            "accordion": "sequence/accordion.html",
            "grid": "sequence/grid.html",
            "batch_grid": "sequence/batch_grid.html",
        }.get(self.sequence_type)
        if template_name is None:
            raise ValueError(self.sequence_type)
        return template(template_name).render(items=items)


class HTMLCorrelationTable(CorrelationTable):
    def render(self) -> str:
        matrix = self.content["correlation_matrix"]
        table_html = matrix.to_html(float_format=lambda value: f"{value:.3f}") if matrix is not None else ""
