"""Core renderable components."""

from __future__ import annotations

from abc import ABC, abstractmethod
from typing import Any, Callable, Dict, List, Optional, Sequence


class Renderable(ABC):
    def __init__(
        self,
        content: Dict[str, Any],
        name: Optional[str] = None,
        anchor_id: Optional[str] = None,
        classes: Optional[str] = None,
    ):
        self.content = content
        if name is not None:
            self.content["name"] = name
        if anchor_id is not None:
            self.content["anchor_id"] = anchor_id
        if classes is not None:
            self.content["classes"] = classes

    @property
    def name(self) -> str:
        return self.content.get("name", "")

    @property
    def anchor_id(self) -> str:
        return self.content.get("anchor_id", "")

    @property
    def classes(self) -> str:
        return self.content.get("classes", "")

    @abstractmethod
    def render(self) -> Any:
        raise NotImplementedError()

    def __str__(self) -> str:
        return self.__class__.__name__

    @classmethod
    def convert_to_class(cls, obj: "Renderable", flavour_func) -> None:
        obj.__class__ = cls


class ItemRenderer(Renderable, ABC):
    def __init__(
        self,
        item_type: str,
        content: dict,
        name: Optional[str] = None,
        anchor_id: Optional[str] = None,
        classes: Optional[str] = None,
    ):
        self.item_type = item_type
        super().__init__(content, name=name, anchor_id=anchor_id, classes=classes)


class HTML(ItemRenderer):
    def __init__(self, html: str, **kwargs):
        super().__init__("html", {"html": html}, **kwargs)

    def render(self) -> Any:
        raise NotImplementedError()


class Alerts(ItemRenderer):
    def __init__(self, alerts, style, **kwargs):
        super().__init__("alerts", {"alerts": alerts, "style": style}, **kwargs)

    def __repr__(self) -> str:
        return "Alerts"

    def render(self) -> Any:
        raise NotImplementedError()


class ToggleButton(ItemRenderer):
    def __init__(self, text: str, **kwargs):
        super().__init__("toggle_button", {"text": text}, **kwargs)

    def __repr__(self) -> str:
        return "ToggleButton"

    def render(self) -> Any:
        raise NotImplementedError()


class Collapse(ItemRenderer):
    def __init__(self, button: ToggleButton, item: Renderable, **kwargs):
        super().__init__("collapse", {"button": button, "item": item}, **kwargs)

    def __repr__(self) -> str:
        return "Collapse"

    def render(self) -> Any:
        raise NotImplementedError()

    @classmethod
    def convert_to_class(cls, obj: Renderable, flv: Callable) -> None:
        obj.__class__ = cls
        flv(obj.content["button"])
        flv(obj.content["item"])


class Container(Renderable):
    def __init__(
        self,
        items: Sequence[Renderable],
        sequence_type: str,
        nested: bool = False,
        name: Optional[str] = None,
        anchor_id: Optional[str] = None,
        classes: Optional[str] = None,
        oss: Optional[bool] = None,
        **kwargs,
    ):
        super().__init__(
            {"items": list(items), "sequence_type": sequence_type, "nested": nested, "oss": oss, **kwargs},
            name=name,
            anchor_id=anchor_id,
            classes=classes,
        )

    @property
    def sequence_type(self) -> str:
        return self.content["sequence_type"]

    def __repr__(self) -> str:
        return f"Container(name={self.name})" if self.name else "Container"

    def render(self) -> Any:
        raise NotImplementedError()

    @classmethod
    def convert_to_class(cls, obj: Renderable, flv: Callable) -> None:
        obj.__class__ = cls
        for item in obj.content.get("items", []):
            flv(item)


class Dropdown(ItemRenderer):
    def __init__(
        self,
        name: str,
        id: str,
        items: list,
        item: Container,
        anchor_id: str,
        classes: list,
        is_row: bool,
        **kwargs,
    ):
        super().__init__(
            "dropdown",
            {
                "name": name,
                "id": id,
                "items": items,
                "item": item,
                "anchor_id": anchor_id,
                "classes": " ".join(classes),
                "is_row": is_row,
            },
            **kwargs,
        )

    def __repr__(self) -> str:
        return "Dropdown"

    def render(self) -> Any:
        raise NotImplementedError()

    @classmethod
    def convert_to_class(cls, obj: Renderable, flv: Callable) -> None:
        obj.__class__ = cls
        flv(obj.content["item"])
        for item in obj.content["items"]:
            if hasattr(item, "render"):
                flv(item)


class Table(ItemRenderer):
    def __init__(
        self,
        rows: Sequence,
        style,
        name: Optional[str] = None,
