"""Variable section renderers."""

from __future__ import annotations

from typing import Any, Dict, List, Tuple, Union

import numpy as np
import pandas as pd

from ydata_profiling.report.presentation.core import (
    Container,
    FrequencyTable,
    FrequencyTableSmall,
    HTML,
    Image,
    Table,
)
from ydata_profiling.report.presentation.frequency_table_utils import extreme_obs_table, freq_table
from ydata_profiling.visualisation.plot import (
    cat_frequency_plot,
    histogram,
    mini_histogram,
    plot_acf_pacf,
    plot_word_cloud,
)


def _series_from_hist(summary: dict, key: str = "histogram") -> Tuple[np.ndarray, np.ndarray]:
    hist = summary.get(key, {})
    return np.asarray(hist.get("counts", [])), np.asarray(hist.get("bin_edges", []))


def render_common(config, summary: dict) -> dict:
    rows = [
        ("Type", summary.get("type")),
        ("Count", summary.get("count", 0)),
        ("Missing", summary.get("n_missing", 0)),
        ("Distinct", summary.get("n_distinct", 0)),
        ("Unique", summary.get("n_unique", 0)),
        ("Memory size", summary.get("memory_size", 0)),
    ]
    return {"rows": rows}


def _get_n(value: Union[list, pd.DataFrame]) -> Union[int, List[int]]:
    if isinstance(value, list):
        return [int(item.sum()) for item in value]
    return int(value.sum())


def render_categorical_frequency(config, summary: dict, varid: str):
    return Table(
        [
            ("Unique values", summary.get("n_unique", 0)),
            ("Unique ratio", summary.get("p_unique", 0.0)),
            ("Distinct ratio", summary.get("p_distinct", 0.0)),
        ],
        style=config.html.style,
        name="Frequency",
        anchor_id=f"{varid}-frequency",
    )


def render_categorical_length(config, summary: dict, varid: str):
    rows = [
        ("Max length", summary.get("max_length", 0)),
        ("Median length", summary.get("median_length", 0)),
        ("Mean length", summary.get("mean_length", 0)),
        ("Min length", summary.get("min_length", 0)),
    ]
    counts, edges = _series_from_hist(summary, "histogram_length")
    image = None
    if len(counts):
        values = np.repeat(edges[:-1], counts.astype(int))
        image = Image(histogram(config, values, bins=max(len(edges) - 1, 1)), config.plot.image_format, alt="Length histogram")
    return Table(rows, style=config.html.style, name="Length", anchor_id=f"{varid}-length"), image


def render_categorical_unicode(config, summary: dict, varid: str):
    table = Table(
        [
            ("Distinct characters", summary.get("n_characters_distinct", 0)),
            ("Characters", summary.get("n_characters", 0)),
        ],
        style=config.html.style,
        name="Characters",
        anchor_id=f"{varid}-characters",
    )
    counts = summary.get("character_counts", pd.Series(dtype=int))
    freq = FrequencyTableSmall(freq_table(counts, _get_n(counts), config.n_freq_table_max), redact=config.vars.cat.redact)
    return table, freq


def render_categorical(config, summary: dict) -> dict:
    common = render_common(config, summary)
    rows = list(common["rows"])
    rows.extend(
        [
            ("Imbalance", summary.get("imbalance", 0.0)),
            ("Top frequency", summary.get("freq", "")),
        ]
    )
    vc = summary.get("value_counts_without_nan", pd.Series(dtype=int))
    visuals = [render_categorical_frequency(config, summary, "cat")]
    if not vc.empty:
        visuals.append(FrequencyTable(freq_table(vc, int(vc.sum()), config.n_freq_table_max), redact=config.vars.cat.redact))
        if config.plot.cat_freq.show and len(vc) <= config.plot.cat_freq.max_unique:
            visuals.append(Image(cat_frequency_plot(config, vc), config.plot.image_format, alt="Category frequency"))
    if "max_length" in summary:
        length_table, length_plot = render_categorical_length(config, summary, "cat")
        visuals.append(length_table)
        if length_plot:
            visuals.append(length_plot)
    if "character_counts" in summary:
        unicode_table, unicode_plot = render_categorical_unicode(config, summary, "cat")
        visuals.extend([unicode_table, unicode_plot])
    return {"rows": rows, "visuals": visuals}


def render_boolean(config, summary: dict) -> dict:
    common = render_common(config, summary)
    vc = summary.get("value_counts_without_nan", pd.Series(dtype=int))
    visuals = []
    if not vc.empty:
        visuals.append(FrequencyTable(freq_table(vc, int(vc.sum()), config.n_freq_table_max), redact=False))
        visuals.append(Image(cat_frequency_plot(config, vc), config.plot.image_format, alt="Boolean frequency"))
    return {"rows": common["rows"] + [("Imbalance", summary.get("imbalance", 0.0))], "visuals": visuals}


def render_real(config, summary: dict) -> dict:
    common = render_common(config, summary)
    rows = list(common["rows"])
    rows.extend(
        [
            ("Mean", summary.get("mean")),
            ("Std", summary.get("std")),
            ("Variance", summary.get("variance")),
            ("Min", summary.get("min")),
            ("Max", summary.get("max")),
            ("Range", summary.get("range")),
            ("Skewness", summary.get("skewness")),
            ("Zeros", summary.get("n_zeros", 0)),
        ]
    )
    visuals = []
    counts, edges = _series_from_hist(summary)
    if len(counts):
        values = np.repeat(edges[:-1], counts.astype(int))
        visuals.append(Image(histogram(config, values, bins=max(len(edges) - 1, 1)), config.plot.image_format, alt="Histogram"))
    vc = summary.get("value_counts_without_nan", pd.Series(dtype=int))
    if not vc.empty:
        visuals.append(FrequencyTableSmall(extreme_obs_table(vc.sort_index(), config.n_extreme_obs, int(vc.sum())), redact=False))
    return {"rows": rows, "visuals": visuals}


def render_date(config, summary: Dict[str, Any]) -> Dict[str, Any]:
    common = render_common(config, summary)
    rows = common["rows"] + [
        ("Min", summary.get("min")),
        ("Max", summary.get("max")),
        ("Range", summary.get("range")),
    ]
    visuals = []
    counts, edges = _series_from_hist(summary)
    if len(counts):
        values = np.repeat(edges[:-1], counts.astype(int))
        visuals.append(Image(histogram(config, values, bins=max(len(edges) - 1, 1), date=True), config.plot.image_format, alt="Date histogram"))
    return {"rows": rows, "visuals": visuals}


def render_text(config, summary: Dict[str, Any]) -> Dict[str, Any]:
    common = render_common(config, summary)
    rows = list(common["rows"])
    for key in ("max_length", "mean_length", "median_length", "min_length", "max_words", "mean_words", "median_words", "min_words"):
        if key in summary:
            rows.append((key.replace("_", " ").title(), summary.get(key)))
    visuals = []
    if "word_counts" in summary and len(summary["word_counts"]) > 0:
        visuals.append(Image(plot_word_cloud(config, summary["word_counts"]), config.plot.image_format, alt="Word cloud"))
    vc = summary.get("value_counts_without_nan", pd.Series(dtype=int))
    if not vc.empty:
        visuals.append(FrequencyTable(freq_table(vc, int(vc.sum()), config.n_freq_table_max), redact=config.vars.text.redact))
    return {"rows": rows, "visuals": visuals}


def _render_gap_tab(config, summary: dict):
    gaps = summary.get("gap_stats", pd.Series(dtype=object))
    rows = [
        ("Number of gaps", int(len(gaps))),
        ("Min gap", gaps.min() if not gaps.empty else ""),
        ("Max gap", gaps.max() if not gaps.empty else ""),
        ("Mean gap", gaps.mean() if not gaps.empty else ""),
        ("Median gap", gaps.median() if not gaps.empty else ""),
    ]
    return Container([Table(rows, style=config.html.style, name="Gap analysis")], sequence_type="named_list", name="Gaps")


def render_timeseries(config, summary: dict) -> dict:
    rendered = render_real(config, summary)
    rendered["rows"].extend(
        [
            ("Stationary", summary.get("is_stationary")),
            ("ADF p-value", summary.get("adfuller_pvalue")),
            ("Seasonality", summary.get("seasonality_presence")),
        ]
    )
    values = summary.get("value_counts_without_nan", pd.Series(dtype=int))
    if hasattr(summary.get("first_rows"), "index"):
        pass
    if "mini_ts" in summary:
        rendered["visuals"].append(HTML(summary["mini_ts"]))
    if summary.get("count", 0) > 3 and "series" in summary:
        rendered["visuals"].append(Image(plot_acf_pacf(config, summary["series"]), config.plot.image_format, alt="ACF PACF"))
    rendered["visuals"].append(_render_gap_tab(config, summary))
    return rendered


def render_url(config, summary: dict) -> dict:
    common = render_common(config, summary)
    rows = list(common["rows"])
    for key in ("scheme_counts", "netloc_counts", "path_counts", "query_counts", "fragment_counts"):
        counts = summary.get(key, pd.Series(dtype=int))
        if len(counts):
            rows.append((key.replace("_", " ").title(), counts.index[0]))
    return {"rows": rows, "visuals": []}


def render_path(config, summary: dict) -> dict:
    common = render_common(config, summary)
    rows = common["rows"] + [("Common prefix", summary.get("common_prefix", ""))]
    return {"rows": rows, "visuals": []}


def render_file(config, summary: dict) -> dict:
    common = render_common(config, summary)
    rows = common["rows"] + [
        ("File size", summary.get("file_size", "")),
        ("Created", summary.get("file_created_time", "")),
        ("Modified", summary.get("file_modified_time", "")),
    ]
    return {"rows": rows, "visuals": []}


def render_image(config, summary: dict) -> dict:
    common = render_common(config, summary)
    rows = common["rows"] + [
        ("Truncated images", summary.get("n_truncated", 0)),
        ("Duplicate hashes", summary.get("n_duplicate_hashes", 0)),
    ]
    return {"rows": rows, "visuals": []}


def render_generic(config, summary: dict) -> dict:
    return render_common(config, summary)


def render_complex(config, summary: dict) -> dict:
    return render_common(config, summary)


def render_count(config, summary: dict) -> dict:
    return render_common(config, summary)

