from __future__ import annotations

import json
from datetime import datetime
from typing import Any

from ydata_profiling.report.formatters import list_args
from ydata_profiling.report.presentation.core import Alerts, Container, HTML, Table
from ydata_profiling.report.presentation.flavours.html.templates import template
from ydata_profiling.visualisation.plot import mini_ts_plot


def get_dataset_overview(config, summary) -> Container:
    table = summary.table
    overview_rows = [
        ("Number of variables", table.get("n_var", 0)),
        ("Number of observations", table.get("n", 0)),
        ("Missing cells", table.get("n_cells_missing", 0)),
        ("Duplicate rows", table.get("n_duplicates", 0)),
        ("Memory size", table.get("memory_size", 0)),
    ]
    type_rows = [(key, value) for key, value in table.get("types", {}).items()]
    return Container(
        [
            Table(overview_rows, style=config.html.style, name="Dataset statistics"),
            Table(type_rows, style=config.html.style, name="Variable types"),
        ],
        sequence_type="named_list",
        name="Overview",
        anchor_id="overview",
    )


def get_dataset_schema(config, metadata: dict) -> Container:
    rows = [(key.replace("_", " ").title(), value) for key, value in metadata.items() if value]
    return Container(
        [Table(rows, style=config.html.style, name="Dataset schema")],
        sequence_type="named_list",
        name="Schema",
        anchor_id="schema",
    )


def get_dataset_reproduction(config, summary):
    @list_args
    def fmt_version(version: str) -> str:
        return f'<a href="https://github.com/ydataai/ydata-profiling">{version}</a>'

    @list_args
    def fmt_config(config_value: str) -> str:
        payload = json.dumps(config_value)
        return f'<a download="config.json" href="data:application/json,{payload}">config.json</a>'

    rows = [
        ("Start", summary.analysis.date_start),
        ("End", summary.analysis.date_end),
        ("Duration", summary.analysis.duration),
        ("Version", fmt_version(summary.package.get("ydata_profiling_version", ""))),
        ("Configuration", fmt_config(summary.package.get("ydata_profiling_config", {}))),
    ]
    return Table(rows, style=config.html.style, name="Reproduction")


def get_dataset_column_definitions(config, definitions: dict) -> Container:
    rows = [(key, value) for key, value in definitions.items()]
    return Container(
        [Table(rows, style=config.html.style, name="Column descriptions")],
        sequence_type="named_list",
        name="Definitions",
        anchor_id="definitions",
    )


def get_dataset_alerts(config, alerts: list) -> Alerts:
    return Alerts(alerts=alerts, style=config.html.style, name="Alerts", anchor_id="alerts")


def get_timeseries_items(config, summary) -> Container:
    @list_args
    def fmt_tsindex_limit(limit: Any) -> str:
        if isinstance(limit, datetime):
            return limit.strftime("%Y-%m-%d %H:%M:%S")
        return str(limit)

    ts = summary.time_index_analysis
    rows = [
        ("Series", ts.n_series),
        ("Length", ts.length),
        ("Start", fmt_tsindex_limit(ts.start)),
        ("End", fmt_tsindex_limit(ts.end)),
        ("Period", ts.period),
        ("Frequency", ts.frequency),
    ]
    plots = []
    numeric_series = []
    for name, desc in summary.variables.items():
        if desc.get("type") == "TimeSeries" and "mini_ts" in desc:
            plots.append(HTML(desc["mini_ts"]))
    return Container(
        [Table(rows, style=config.html.style, name="Time index analysis"), *plots],
        sequence_type="named_list",
        name="Time series",
        anchor_id="time-series",
    )


def get_dataset_items(config, summary, alerts: list) -> list:
    items = [get_dataset_overview(config, summary)]
    if any(value for value in config.dataset.dict().values()):
        items.append(get_dataset_schema(config, config.dataset.dict()))
    if config.variables.descriptions:
        items.append(get_dataset_column_definitions(config, config.variables.descriptions))
    if summary.time_index_analysis is not None:
        items.append(get_timeseries_items(config, summary))
    items.append(get_dataset_alerts(config, alerts))
    items.append(get_dataset_reproduction(config, summary))
    return items

