"""Expectation-suite integration."""

from __future__ import annotations

from typing import Any, Optional

from ydata_profiling.model.expectation_algorithms import (
    categorical_expectations,
    datetime_expectations,
    file_expectations,
    generic_expectations,
    image_expectations,
    numeric_expectations,
    path_expectations,
    url_expectations,
)
from ydata_profiling.model.handler import Handler


class ExpectationHandler(Handler):
    """Default expectation handler."""

    def __init__(self, typeset, *args, **kwargs):
        mapping = {
            "Unsupported": [generic_expectations],
            "Text": [categorical_expectations],
            "Categorical": [categorical_expectations],
            "Boolean": [categorical_expectations],
            "Numeric": [numeric_expectations],
            "TimeSeries": [numeric_expectations],
            "URL": [url_expectations],
            "File": [file_expectations],
            "Path": [path_expectations],
            "DateTime": [datetime_expectations],
            "Image": [image_expectations],
        }
        super().__init__(mapping, typeset, *args, **kwargs)


class ExpectationsReport:
    config = None
    df = None

    @property
    def typeset(self):
        return None

    def to_expectation_suite(
        self,
        suite_name: Optional[str] = None,
        data_context: Optional[Any] = None,
        save_suite: bool = True,
        run_validation: bool = True,
        build_data_docs: bool = True,
        handler: Optional[Handler] = None,
    ) -> Any:
        description = self.get_description()
        handler = handler or ExpectationHandler(self.typeset)
        suite = {"name": suite_name or self.config.title, "expectations": []}
        for name, summary in description.variables.items():
            batch = {"expectations": []}
            _, _, batch = generic_expectations(name, summary, batch)
            result = handler.handle(summary.get("type", "Unsupported"), name, summary, batch)
            if isinstance(result, dict) and "expectations" in result:
                suite["expectations"].extend(result["expectations"])
            else:
                suite["expectations"].extend(batch["expectations"])
        if data_context is not None and hasattr(data_context, "add_expectation_suite"):
            try:
                data_context.add_expectation_suite(expectation_suite=suite)
            except Exception:
                pass
        return suite

