from __future__ import annotations

import pickle
from pathlib import Path
from typing import Optional, Union

from ydata_profiling.utils.dataframe import hash_dataframe


class SerializeReport:
    """Extend the report to be able to dump and load reports."""

    df = None
    config = None
    _df_hash: Optional[str] = None
    _report = None
    _description_set = None

    @property
    def df_hash(self) -> Optional[str]:
        if self._df_hash is None and self.df is not None:
            try:
                self._df_hash = hash_dataframe(self.df)
            except Exception:
                self._df_hash = None
        return self._df_hash

    def dumps(self) -> bytes:
        return pickle.dumps(self)

    def loads(self, data: bytes):
        return pickle.loads(data)

    def dump(self, output_file: Union[Path, str]) -> None:
        Path(output_file).write_bytes(self.dumps())

    def load(self, load_file: Union[Path, str]):
        return self.loads(Path(load_file).read_bytes())

