"""Comparison helpers."""

from __future__ import annotations

import warnings
from dataclasses import replace
from typing import Any, List, Optional, Tuple, Union

import pandas as pd

from ydata_profiling.model.description import BaseAnalysis, BaseDescription, TimeIndexAnalysis


def _should_wrap(v1: Any, v2: Any) -> bool:
    if isinstance(v1, (list, tuple, dict)) or isinstance(v2, (list, tuple, dict)):
        return False
    if isinstance(v1, pd.DataFrame) and isinstance(v2, pd.DataFrame):
        return not v1.equals(v2)
    if isinstance(v1, pd.Series) and isinstance(v2, pd.Series):
        return not v1.equals(v2)
    try:
        return v1 != v2
    except ValueError:
        return True


def _update_merge_seq(d1: Any, d2: Any) -> Union[list, tuple]:
    left = list(d1) if isinstance(d1, (list, tuple)) else [d1]
    right = list(d2) if isinstance(d2, (list, tuple)) else [d2]
    return tuple(left + right) if isinstance(d1, tuple) or isinstance(d2, tuple) else left + right


def _update_merge_mixed(d1: Any, d2: Any) -> Union[dict, list, tuple]:
    if isinstance(d1, dict) and isinstance(d2, dict):
        return _update_merge_dict(d1, d2)
    return _update_merge_seq(d1, d2)


def _update_merge_dict(d1: Any, d2: Any) -> dict:
    result = {**d1, **d2}
    for key in set(d1) & set(d2):
        v1 = d1[key]
        v2 = d2[key]
        if isinstance(v1, dict) and isinstance(v2, dict):
            result[key] = _update_merge_dict(v1, v2)
        elif _should_wrap(v1, v2):
            result[key] = _update_merge_mixed(v1, v2)
        else:
            result[key] = v1
    return result


def _update_merge(d1: Optional[dict], d2: dict) -> dict:
    if d1 is None:
        return d2
    if not isinstance(d1, dict) or not isinstance(d2, dict):
        raise TypeError("Expected dictionaries")
    return _update_merge_dict(d1, d2)


def _placeholders(reports: List[BaseDescription]) -> None:
    scatter_keys = set()
    type_keys = set()
    for report in reports:
        scatter_keys |= set(report.scatter.keys())
        type_keys |= set(report.table.get("types", {}).keys())
    for report in reports:
        for key in scatter_keys:
            report.scatter.setdefault(key, {})
        for key in type_keys:
            report.table.setdefault("types", {}).setdefault(key, 0)


def _update_titles(reports: List["ProfileReport"]) -> None:
    for idx, report in enumerate(reports):
        if report.config.title == "YData Profiling Report":
            report.config.title = f"Dataset {chr(65 + idx)}"


def _compare_profile_report_preprocess(
    reports: List["ProfileReport"],
    config=None,
) -> Tuple[List[str], List[BaseDescription]]:
    _update_titles(reports)
    labels = [report.config.title for report in reports]
    descriptions = [report.get_description() for report in reports]
    if config is not None:
        config.html.style._labels = labels
    else:
        reports[0].config.html.style._labels = labels
    return labels, descriptions


def _compare_dataset_description_preprocess(
    reports: List[BaseDescription],
) -> Tuple[List[str], List[BaseDescription]]:
    return [report.analysis.title for report in reports], reports


def _apply_config(description: BaseDescription, config) -> BaseDescription:
    if not config.missing_diagrams:
        description.missing = {}
    if not config.correlations:
        description.correlations = {}
    return description


def _is_alert_present(alert, alert_list: list) -> bool:
    return any(
        existing.column_name == alert.column_name and existing.alert_type == alert.alert_type for existing in alert_list
    )


def _create_placehoder_alerts(report_alerts: tuple) -> tuple:
    return report_alerts


def _compare_title(titles: List[str]) -> str:
    return " vs ".join(titles)


def validate_reports(
    reports: Union[List["ProfileReport"], List[BaseDescription]], configs: List[dict]
) -> None:
    if len(reports) < 2:
        raise ValueError("At least two reports are required for comparison.")
    if len(reports) > 2:
        warnings.warn("Comparing more than two reports is only partially supported.", stacklevel=2)


def compare(
    reports: Union[List["ProfileReport"], List[BaseDescription]],
    config=None,
    compute: bool = False,
):
    from ydata_profiling.profile_report import ProfileReport

    validate_reports(reports, [])
    if all(isinstance(report, ProfileReport) for report in reports):
        labels, descriptions = _compare_profile_report_preprocess(reports, config=config)
        base_config = config or reports[0].config
    elif all(isinstance(report, BaseDescription) for report in reports):
        labels, descriptions = _compare_dataset_description_preprocess(reports)
        from ydata_profiling.config import Settings

        base_config = config or Settings(title=_compare_title(labels))
    else:
        raise TypeError("Reports must all be ProfileReport or all BaseDescription objects.")

    _placeholders(descriptions)
    merged_table = None
    merged_variables = None
    merged_scatter = None
    merged_correlations = None
    merged_missing = None
    merged_package = None
    samples = []
    duplicates = []
    date_starts = []
    date_ends = []
    alerts = []
    for description in descriptions:
        merged_table = _update_merge(merged_table, description.table)
        merged_variables = _update_merge(merged_variables, description.variables)
        merged_scatter = _update_merge(merged_scatter, description.scatter)
        merged_correlations = _update_merge(merged_correlations, description.correlations)
        merged_missing = _update_merge(merged_missing, description.missing)
        merged_package = _update_merge(merged_package, description.package)
        samples.append(description.sample)
        duplicates.append(description.duplicates)
        date_starts.append(description.analysis.date_start)
        date_ends.append(description.analysis.date_end)
        alerts.append(description.alerts)
    analysis = BaseAnalysis(title=_compare_title(labels), date_start=date_starts, date_end=date_ends)
    time_index = None
    if any(report.time_index_analysis is not None for report in descriptions):
        values = [report.time_index_analysis for report in descriptions if report.time_index_analysis is not None]
        time_index = TimeIndexAnalysis(
            n_series=[value.n_series for value in values],
            length=[value.length for value in values],
            start=[value.start for value in values],
            end=[value.end for value in values],
            period=[value.period for value in values],
            frequency=[value.frequency for value in values],
        )
    merged = BaseDescription(
        analysis=analysis,
        time_index_analysis=time_index,
        table=merged_table or {},
        variables=merged_variables or {},
